			"predicate":        k.Predicate,
			"supplier":         k.Supplier,
			"seat":             "prerequisites",
			"rfc":              "RFC_056",
			"observed_at":      observedAt,
			"absence":          k.Absence,
			"not_dispatchable": buildPrerequisitesNotDispatchable,
